import {Dojo,ACTIONS} from './training-engine.mjs';
import {FirstPerson} from './first-person.mjs';
import {KaiRenderer,coachPose} from './kai-reference-renderer.mjs';
import {KAI,LEVELS,STRIKES} from './kai.mjs';
const $=s=>document.querySelector(s),canvas=$('#arena'),ctx=canvas.getContext('2d'),game=new Dojo();
const particles=[],povImage=new Image(),pov=new FirstPerson(povImage),coach=new KaiRenderer();game.lockFacing=true;
let W=960,H=540,last=0,loaded=false,sound=false,audio,shake=0,dummyKick=0,dummyWobble=0,lastHud=-1,activePointers=new Map();
const colors={night:'#16283b',ink:'#101c2c',wood:'#624238',gold:'#e6bc78',light:'#ffdc91'};
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function resize(){const box=$('#stage').getBoundingClientRect(),dpr=Math.min(3,window.devicePixelRatio||1);W=Math.max(480,Math.round(box.width*dpr));H=Math.round(W*box.height/box.width);canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';}
new ResizeObserver(resize).observe($('#stage'));
function tone(hz=220,d=.08,kind='sine',gain=.07){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),g=audio.createGain();osc.type=kind;osc.frequency.setValueAtTime(hz,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(30,hz*.35),audio.currentTime+d);g.gain.setValueAtTime(gain,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);osc.connect(g);g.connect(audio.destination);osc.start();osc.stop(audio.currentTime+d);}catch{}}
Promise.all([new Promise((resolve,reject)=>{povImage.onload=()=>{try{pov.prepare();resolve();}catch(e){reject(e);}};povImage.onerror=()=>reject(Error('第一人稱素材載入失敗'));povImage.src='assets/first-person-atlas.png';}),coach.load()]).then(()=>{loaded=true;$('#start').disabled=false;$('#start').textContent='開始跟練 →';$('#loadStatus').textContent='看招 → 點一下格擋 → 左右拳腳反擊';}).catch(e=>{$('#loadStatus').textContent=e.message+'，請重新整理再試。';$('#start').textContent='角色素材尚未載入';});
function drawCoach(t,x,y,scale){coach.draw(ctx,game,t,x,y,scale*200);}
function burst(x,y,type){const c=type==='guard'?'#bfe8d3':'#ffd48b';for(let i=0;i<14;i++){const a=i/14*Math.PI*2;particles.push({x,y,vx:Math.cos(a)*(70+Math.random()*170),vy:Math.sin(a)*(70+Math.random()*170),life:.24+Math.random()*.2,color:c});}}
function render(dt,t){ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake=Math.max(0,shake-dt*55);}pov.scene(ctx,W,H,game,t,drawCoach);pov.hands(ctx,W,H,game,t);for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;rect(p.x,p.y,4,4,p.color);if(p.life<=0)particles.splice(i,1);}ctx.restore();dummyWobble=Math.max(0,dummyWobble-dt*4);dummyKick=Math.max(0,dummyKick-dt*7);
 if(game.counterReady){rect(W*.35,H*.14,W*.3,5,'#172637');rect(W*.35,H*.14,W*.3*Math.max(0,(game.counterUntil-game.now)/1.25),5,'#9ed8bc');}
 if(game.cue){const progress=Math.min(1,(game.now-game.cue.at)/game.cue.delay);rect(W*.35,H*.19,W*.3,4,'#171e2d');rect(W*.35,H*.19,W*.3*(1-progress),4,'#efbc68');}
}
function actionKey(){const a=game.preview?.action||game.action;if(game.preview?.key)return game.preview.key;if(a==='punch'||a==='kick')return a+(game.attackSide==='left'?'Left':'Right');if(a==='block')return 'block'+game.guardLevel[0].toUpperCase()+game.guardLevel.slice(1);return a;}
function actionLabel(){if(game.coachPreview)return '凱師範・'+LEVELS[game.coachPreview]+['架勢','蓄勢','出招','出腳'][coachPose(game).row];const key=actionKey();return STRIKES[key]?.label||({blockHigh:'上段格擋',blockMid:'中段格擋',blockLow:'下段格擋'}[key])||ACTIONS[game.preview?.action||game.action].label.split(' / ')[0];}
function hud(){const preview=game.preview?.action;$('#healthText').textContent=game.hp+' / 100';$('#healthBar').style.width=game.hp+'%';$('#timer').textContent=game.mode==='free'?'∞':Math.ceil(game.timeLeft);$('#hits').textContent=game.hits;$('#guards').textContent=game.guards;$('#best').innerHTML=(game.best===null?'—':game.best.toFixed(2))+'<small>秒</small>';$('#feedback').textContent=preview?'動作預覽：'+actionLabel():game.message;const defending=!!game.cue,counter=game.counterReady;$('#cue').textContent=preview?'動作示範 · '+actionLabel():counter?'擋住了！換你反擊':defending?(game.mode==='free'?'擋'+LEVELS[game.cue.level]+' · 點一下即可':'觀察起手 · 擋對高度'):game.phase==='recover'?'收招回防 · 準備下一招':'回到架勢 · 等待起手';$('#cue').classList.toggle('threat',defending);$('#cue').classList.toggle('counter',counter);document.querySelectorAll('[data-step]').forEach(el=>el.classList.toggle('current',el.dataset.step===(counter?'counter':defending?'defend':'ready')));document.querySelectorAll('[data-act]').forEach(el=>{el.classList.toggle('available',counter);el.setAttribute('aria-disabled',String(!counter));});$('#actionLabel').textContent=actionLabel();document.querySelectorAll('[data-preview]').forEach(b=>b.classList.toggle('selected',b.dataset.preview===actionKey()));
 for(const b of document.querySelectorAll('[data-hold]'))b.classList.toggle('active',game.held[b.dataset.hold]);for(const b of document.querySelectorAll('[data-act]'))b.classList.toggle('active',actionKey()===b.dataset.act);
}
function processEvents(){for(const e of game.events.splice(0)){if(e.type==='impact'){dummyWobble=1;shake=5;burst(W*.5,H*.5,'hit');tone(e.action==='kick'?100:160,.1,'triangle',.10);}
 else if(e.type==='swing')tone(380,.06,'triangle',.025);
 else if(e.type==='cue')tone(720,.1,'sine',.06);
 else if(e.type==='guard'){dummyKick=1;burst(W*.5,H*.53,'guard');tone(950,.09,'triangle',.09);$('#reaction').textContent='反應 '+e.reaction.toFixed(2)+' 秒';}
 else if(e.type==='hurt'){dummyKick=1;shake=7;tone(80,.18,'sawtooth',.06);}
 else if(e.type==='end'){release();$('#resultTitle').textContent=game.hp>0?'本回合完成':'稍作休息，再來一次';$('#resultSummary').textContent='成功防守 '+game.guards+' 次 / 師範出招 '+game.attempts+' 次，反擊命中 '+game.hits+' 次。'+(game.best!==null?'最佳反應 '+game.best.toFixed(2)+' 秒。':'看到起手後點一下格擋，成功後接反擊。');$('#resultOverlay').hidden=false;$('#pause').disabled=true;$('#again').focus();}}}
function loop(ts){const dt=Math.min(.05,(ts-last)/1000||0);last=ts;game.update(dt);processEvents();render(game.paused?0:dt,game.now);if(ts-lastHud>70){hud();lastHud=ts;}requestAnimationFrame(loop);}requestAnimationFrame(loop);
function setHold(source,action,on){if(on)activePointers.set(source,action);else activePointers.delete(source);game.hold(action,[...activePointers.values()].includes(action));}
function release(){game.releaseAll();activePointers.clear();document.querySelectorAll('.controls button').forEach(b=>b.classList.remove('active'));}
function start(mode){release();game.start(mode);particles.length=0;$('#intro').hidden=true;$('#pauseOverlay').hidden=true;$('#resultOverlay').hidden=true;$('#pause').disabled=false;$('#modeLabel').textContent=mode==='free'?'GUIDED TRAINING':'REACTION CHALLENGE';$('#freeMode').setAttribute('aria-pressed',String(mode==='free'));$('#challengeMode').setAttribute('aria-pressed',String(mode==='challenge'));$('#modeHelp').textContent=mode==='free'?'慢速、有高度提示、不扣血。看起手，點一下對應格擋；成功後在 1.25 秒內選一招反擊。':'45 秒隨機攻防。從姿勢判斷高度，擋成功才開放一次反擊；連續成功會逐漸加快。';$('#reaction').textContent='反應 —';tone(440,.12);hud();}
$('#start').onclick=()=>start('free');$('#freeMode').onclick=()=>{if(loaded)start('free');};$('#challengeMode').onclick=()=>{if(loaded)start('challenge');};$('#again').onclick=()=>start('challenge');$('#back').onclick=()=>start('free');
function pause(){if(!game.started||game.finished)return;game.pause();release();$('#pauseOverlay').hidden=false;$('#resume').focus();hud();}function resume(){game.resume();$('#pauseOverlay').hidden=true;last=performance.now();}$('#pause').onclick=pause;$('#resume').onclick=resume;
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='音效 '+(sound?'開':'關');$('#sound').setAttribute('aria-pressed',String(sound));if(sound)tone(440,.15);};
let accessibleSerial=0;
for(const b of document.querySelectorAll('.controls button')){b.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;if(!game.started||game.paused||game.finished)return;e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.hold)setHold('pointer:'+e.pointerId,b.dataset.hold,true);else game.act(b.dataset.act);hud();});const up=e=>{const source='pointer:'+e.pointerId,a=activePointers.get(source);if(a)setHold(source,a,false);hud();};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,up);b.addEventListener('click',e=>{if(e.detail!==0||!game.started||game.paused||game.finished)return;if(b.dataset.hold){const source='accessible:'+accessibleSerial++;setHold(source,b.dataset.hold,true);setTimeout(()=>{setHold(source,b.dataset.hold,false);hud();},300);}else game.act(b.dataset.act);hud();});}
for(const b of document.querySelectorAll('[data-preview]'))b.onclick=()=>{if(!loaded)return;if(!game.started||game.finished)start('free');if(game.paused)resume();game.inspect(b.dataset.preview);hud();};
const keys={i:'blockHigh',k:'blockMid',m:'blockLow'},strikes={f:'punchLeft',j:'punchRight',v:'kickLeft',n:'kickRight'};
document.addEventListener('keydown',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(!game.started||game.finished||e.altKey||e.ctrlKey||e.metaKey)return;if(key==='Escape'){e.preventDefault();game.paused?resume():pause();return;}if(e.target.closest('button')&&(key===' '||key==='Enter'))return;if(keys[key]){e.preventDefault();if(!game.paused&&!e.repeat)setHold('key:'+key,keys[key],true);}else if(strikes[key]&&!e.repeat){e.preventDefault();game.act(strikes[key]);}hud();});document.addEventListener('keyup',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(keys[key]){e.preventDefault();setHold('key:'+key,keys[key],false);hud();}});window.addEventListener('blur',()=>{release();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){release();pause();}});

for(const b of document.querySelectorAll('[data-coach]'))b.onclick=()=>{if(!loaded)return;if(!game.started||game.finished)start('free');if(game.paused)resume();game.inspect('idle');game.coachPreview=b.dataset.coach;game.enemyAttack={level:b.dataset.coach,side:'right',until:game.now+2.4};hud();$('#stage').scrollIntoView({block:'center'});};

